def boot_ci(diffs: list[float], iters: int = 10_000, seed: int = 42) -> tuple[float, float, float]:
    arr = np.array(diffs)
    rng = np.random.default_rng(seed)
    boot = np.array([
        arr[rng.integers(0, len(arr), size=len(arr))].mean()
        for _ in range(iters)
