            return out
        for paper_dir in eval_dir.iterdir():
            if not paper_dir.is_dir():
                continue
            for ep in paper_dir.glob("*.eval.json"):
                try:
                    d = json.loads(ep.read_text())
                except Exception:
                    continue
                if d.get("error"):
                    continue
                if eval_dir_name != "evals":
                    if d.get("paper_recall", -1) == 0.0 and d.get("evidence_coverage", 0) > 0:
