def win_loss_tie(
    a: Sequence[float], b: Sequence[float], tol: float = 0.02,
) -> tuple[int, int, int]:
    wins = losses = ties = 0
    for ai, bi in zip(a, b):
        d = ai - bi
        if d > tol:
            wins += 1
        elif d < -tol:
            losses += 1
        else:
            ties += 1
    return wins, losses, ties
